package com.example.ungdungchiasecaycanh.ui.community;
import static org.junit.Assert.*;import com.example.ungdungchiasecaycanh.model.*;import com.google.firebase.Timestamp;import java.util.*;import org.junit.Test;
public class PostDetailViewModelTest{
 private Comment c(String id,String parent,long second){return new Comment(id,"u",parent,id,new Timestamp(second,0));}
 @Test public void groupingPlacesRepliesBelowParentAndSkipsOrphan(){List<Comment> source=Arrays.asList(c("c2","",4),c("r2","c1",3),c("c1","",1),c("orphan","missing",2),c("r1","c1",2));List<CommunityCommentItem> out=PostDetailViewModel.group(source,Collections.emptyMap());assertEquals(4,out.size());assertEquals("c1",out.get(0).comment.getCommentId());assertEquals("r1",out.get(1).comment.getCommentId());assertEquals("r2",out.get(2).comment.getCommentId());assertEquals("c2",out.get(3).comment.getCommentId());}
 @Test public void collapsedThreadShowsOneMoreRow(){List<Comment> source=Arrays.asList(c("c1","",1),c("r1","c1",2),c("r2","c1",3),c("c2","",4));List<CommunityCommentItem> out=PostDetailViewModel.group(source,Collections.emptyMap(),new HashSet<>());assertEquals(3,out.size());assertNull(out.get(1).comment);assertEquals(2,out.get(1).moreCount);assertEquals("c1",out.get(1).threadId);List<CommunityCommentItem> open=PostDetailViewModel.group(source,Collections.emptyMap(),new HashSet<>(Collections.singleton("c1")));assertEquals(4,open.size());assertEquals("c1",open.get(2).threadId);}
 @Test public void mentionPointsToThatMember(){Map<String,String> names=new HashMap<>();names.put("u1","Vy");names.put("u2","Thảo Vy");assertEquals("u2",PostDetailViewModel.mentionedUid("@Thảo Vy ok",names));assertEquals("",PostDetailViewModel.mentionedUid("Thảo Vy",names));assertEquals("",PostDetailViewModel.mentionedUid("@Lan hi",names));assertEquals("u1",PostDetailViewModel.mentionedUid("@Vy ơi",names));}
 @Test public void listingContextTracksId(){assertFalse(PostDetailViewModel.hasListingContext(new Post("p","u","x",PostCategory.GENERAL,"","",null)));assertTrue(PostDetailViewModel.hasListingContext(new Post("p","u","x",PostCategory.SHARING,"l","",null)));}
}
